# Generated by build.py from recipe.yml for recipe smtp-load-mailboxes-from-a-csv-file. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'make-mailboxes.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Writes mailboxes.csv: forty test mailboxes, tester01 to tester40. The last ten log in over IMAP`n# only; the rest have an empty protocols field, which means every mail protocol.`necho `"address,password,protocols`" > mailboxes.csv`ni=1`nwhile [ `"`$i`" -le 40 ]; do`n  n=`$(printf '%02d' `"`$i`")`n  if [ `"`$i`" -le 30 ]; then protocols=`"`"; else protocols=`"imap`"; fi`n  echo `"tester`$n@example.com,pass`$n,`$protocols`" >> mailboxes.csv`n  i=`$((i + 1))`ndone`n")
[IO.File]::WriteAllText((Join-Path $PWD 'quoted.csv'), "address,password,protocols`nops@example.com,`"s3cret,too`",imap`n")
[IO.File]::WriteAllText((Join-Path $PWD 'outside.csv'), "address,password,protocols`nops@example.com,`"s3cret,too`",imap`n`ncarol@elsewhere.org,carolpass,`n")
[IO.File]::WriteAllText((Join-Path $PWD 'again.csv'), "address,password`ntester05@example.com,another`n")
[IO.File]::WriteAllText((Join-Path $PWD 'columns.csv'), "address,pass`nann@example.com,annpass`n")
[IO.File]::WriteAllText((Join-Path $PWD 'note.eml'), "From: tester01@example.com`nTo: tester02@example.com`nSubject: Build 812 passed`n`nAll 40 suites passed.`n")
cmd /c 'sh make-mailboxes.sh'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--mail-domain', 'example.com', '--mailbox-file', 'mailboxes.csv', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/', 'pop3://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --crlf -u tester01@example.com:pass01 --mail-from tester01@example.com --mail-rcpt tester02@example.com -T note.eml smtp://127.0.0.1:8080/ci.example.com --next -sS --retry 10 --retry-all-errors --retry-delay 1 -u tester02@example.com:pass02 "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(SUBJECT)" } finally { Stop-Process $server0 }
